def find(p,x):
    while p[x]!=x:
        p[x]=p[p[x]]
        x=p[x]
    return x
def union(p,a,b):
    ra,rb=find(p,a),find(p,b)
    if ra!=rb:
        p[rb]=ra
verts=['A','B','C','D','E']
edges=[('A','B',4),('A','C',8),('B','C',11),('C','D',7),('C','E',2),('D','E',9)]
p={v:v for v in verts}
mst=0
rounds=0
while True:
    roots={}
    for v in verts:
        r=find(p,v)
        roots.setdefault(r,[]).append(v)
    if len(roots)==1:
        break
    best={}
    for u,v,w in edges:
        ru,rv=find(p,u),find(p,v)
        if ru==rv:
            continue
        if ru not in best or w<best[ru][0]:
            best[ru]=(w,u,v)
        if rv not in best or w<best[rv][0]:
            best[rv]=(w,u,v)
    added=False
    for w,u,v in best.values():
        if find(p,u)!=find(p,v):
            union(p,u,v)
            mst+=w
            added=True
    rounds+=1
    if not added:
        break
print(mst)
print(rounds)
